import androidx.compose.ui.unit.dp
internal enum class PlayerSymbol {
    Play, Pause, Previous, Next, More, Route, Star,
    Shuffle, Repeat, RepeatOne,
    ModeShuffle, ModeRepeat, ModeRepeatOne, ModeAutoplay,
    MiniPlay, MiniPause, MiniNext, Lossless, Atmos,
    Translations,
}
internal val PlayerSymbol.intrinsicSize: DpSize
    get() = when (this) {
        PlayerSymbol.Play, PlayerSymbol.Pause -> DpSize(38.dp, 38.dp)
        PlayerSymbol.Previous, PlayerSymbol.Next -> DpSize(40.dp, 34.dp)
        PlayerSymbol.ModeShuffle, PlayerSymbol.ModeRepeat, PlayerSymbol.ModeRepeatOne, PlayerSymbol.ModeAutoplay -> DpSize(38.dp, 38.dp)
        PlayerSymbol.MiniPlay, PlayerSymbol.MiniPause, PlayerSymbol.MiniNext -> DpSize(32.dp, 32.dp)
        PlayerSymbol.Translations -> DpSize(36.dp, 36.dp)
        PlayerSymbol.Lossless -> DpSize(14.dp, 9.dp)
        PlayerSymbol.Atmos -> DpSize(83.dp, 15.dp)
        else -> DpSize(28.dp, 28.dp)
    }

// Matches autoMirrored on the source now-playing vectors.
private val mirroredSymbols = setOf(PlayerSymbol.Star, PlayerSymbol.Shuffle)


/** Vector silhouettes drawn at the original control's intrinsic size, separate from its larger touch target. */
@Composable
internal fun PlayerGlyph(symbol: PlayerSymbol, description: String?, tint: Color, modifier: Modifier, selected: Boolean = false) {
    val path = remember(symbol, selected) {
        val glyph = glyphPath(symbol, selected)
        if (!selected && (symbol == PlayerSymbol.Shuffle || symbol == PlayerSymbol.Repeat || symbol == PlayerSymbol.RepeatOne)) {
            glyph.translate(Offset(14f, 14f) - glyph.getBounds().center)
        }
        glyph
    }
    val accessibility = if (description == null) Modifier else Modifier.semantics { contentDescription = description }
    val layoutDirection = LocalLayoutDirection.current
    val backdrop = remember(symbol, selected) {
        if (symbol == PlayerSymbol.Translations && !selected) vectorPath("M12.819,-0L23.181,0C27.638,-0 29.255,0.464 30.884,1.336C32.514,2.207 33.793,3.486 34.664,5.116C35.536,6.745 36,8.362 36,12.819L36,23.181C36,27.638 35.536,29.255 34.664,30.884C33.793,32.514 32.514,33.793 30.884,34.664C29.255,35.536 27.638,36 23.181,36L12.819,36C8.362,36 6.745,35.536 5.116,34.664C3.486,33.793 2.207,32.514 1.336,30.884C0.464,29.255 0,27.638 -0,23.181L0,12.819C0,8.362 0.464,6.745 1.336,5.116C2.207,3.486 3.486,2.207 5.116,1.336C6.745,0.464 8.362,0 12.819,-0Z", true) else null
    }
    Canvas(modifier.then(accessibility)) {
        val intrinsic = symbol.intrinsicSize
        val reference = Size(intrinsic.width.value, intrinsic.height.value)
        scale(size.width / reference.width, size.height / reference.height, pivot = Offset.Zero) {
            scale(if (symbol in mirroredSymbols && layoutDirection == LayoutDirection.Rtl) -1f else 1f, 1f,
                pivot = Offset(reference.width / 2f, 0f)) {
                when {
                    symbol == PlayerSymbol.More -> {
                        drawCircle(tint.copy(alpha = tint.alpha * .18f), 14f, Offset(14f, 14f))
                        drawPath(path, tint.copy(alpha = tint.alpha * .9f))
                    }
                    symbol == PlayerSymbol.Star && !selected -> {
                        drawCircle(tint.copy(alpha = tint.alpha * .19f), 14f, Offset(14f, 14f))
                        drawPath(path, tint)
                    }
                    else -> {
                        backdrop?.let { drawPath(it, tint.copy(alpha = tint.alpha * .18f)) }
                        drawPath(path, tint)
                    }
                }
            }
        }
    }
}

@Composable
internal fun QueueModeGlyph(symbol: PlayerSymbol, selected: Boolean, enabled: Boolean, modifier: Modifier = Modifier) {
    val path = remember(symbol) { glyphPath(symbol, selected = false) }
    val drawLayer = if (selected && enabled) modifier.graphicsLayer {
        compositingStrategy = CompositingStrategy.Offscreen
    } else modifier
    Canvas(drawLayer) {
        val iconScale = size.height / 38f
        val iconLeft = (size.width - 38f * iconScale) / 2f
        if (selected && enabled) {
            drawRoundRect(Color.White.copy(alpha = .45f), cornerRadius = androidx.compose.ui.geometry.CornerRadius(size.height / 2f))
            withTransform({ translate(iconLeft, 0f); scale(iconScale, iconScale, pivot = Offset.Zero) }) {
                drawPath(path, Color.Black, blendMode = BlendMode.Clear)
            }
        } else {
            withTransform({ translate(iconLeft, 0f); scale(iconScale, iconScale, pivot = Offset.Zero) }) {
                drawPath(path, Color.White.copy(alpha = if (enabled) 1f else .08f))
            }
        }
    }
}

