private fun vectorPath(pathData: String, evenOdd: Boolean = false): Path {
    val path = PathParser.createPathFromPathData(pathData) ?: return Path()
    path.fillType = if (evenOdd) AndroidPath.FillType.EVEN_ODD else AndroidPath.FillType.WINDING
